static gmsg_error link_stuffed_sync_link_stream_process_(gmsg_stream* gs, uint8_t* frame, size_t n) {
    link_stuffed_sync_link_stream* s = (link_stuffed_sync_link_stream*)gs;
    link_stuffed_sync_link_frame_ f;
    gmsg_error e = GMSG_OK;
    if ((e = link_stuffed_sync_link_open_(frame, n, &f)) != GMSG_OK) return e;
    if (s->mode_ == link_stuffed_sync_link_mode_deliver_) {
        link_stuffed_sync_link_any_view v;
        if ((e = link_stuffed_sync_link_select_restore_(frame, n, &f, &v)) != GMSG_OK) return e;
        gs->last_extra = link_stuffed_sync_link_extra_(&v);
        link_stuffed_sync_link_deliver_(&s->cb, &f, &v);
        return GMSG_OK;
    }
    if ((e = link_stuffed_sync_link_select_restore_(frame, n, &f, &s->got_.message)) != GMSG_OK) return e;
    gs->last_extra = s->got_.extra = link_stuffed_sync_link_extra_(&s->got_.message);
    s->got_.header = f.header;
    s->got_.bytes = frame;
    s->got_.size = n;
    if (s->mode_ == link_stuffed_sync_link_mode_for_ && s->got_.message.kind != s->want_) {
        link_stuffed_sync_link_deliver_(&s->cb, &f, &s->got_.message);  /* not the awaited message: to the callbacks */
        s->got_.message.kind = LINK_STUFFED_SYNC_LINK_NONE;
    }
    if (s->mode_ == link_stuffed_sync_link_mode_message_) {
        switch (s->got_.message.kind) {
            case LINK_STUFFED_SYNC_LINK_DATA: s->msg_->kind = LINK_STUFFED_SYNC_LINK_DATA; e = link_stuffed_data_view_to_struct(&s->got_.message.as.data, &s->msg_->as.data); break;
            case LINK_STUFFED_SYNC_LINK_PING: s->msg_->kind = LINK_STUFFED_SYNC_LINK_PING; e = link_stuffed_ping_view_to_struct(&s->got_.message.as.ping, &s->msg_->as.ping); break;
            default: e = GMSG_ERR_UNKNOWN_TYPE; break;
        }
        if (e != GMSG_OK) link_stuffed_sync_link_restore_(frame, n, f.unescaped_n);  /* a frame that fails is left as received */
        return e;
    }
    return GMSG_OK;
}

bool link_stuffed_sync_link_stream_poll(link_stuffed_sync_link_stream* s, link_stuffed_sync_link_any_view* out) {
    bool ok;
    s->mode_ = link_stuffed_sync_link_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = link_stuffed_sync_link_mode_deliver_;
    if (ok) *out = s->got_.message;
    return ok;
}

bool link_stuffed_sync_link_stream_poll_frame(link_stuffed_sync_link_stream* s, link_stuffed_sync_link_received* out) {
    bool ok;
    s->mode_ = link_stuffed_sync_link_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = link_stuffed_sync_link_mode_deliver_;
    if (ok) *out = s->got_;
    return ok;
}

bool link_stuffed_sync_link_stream_poll_message(link_stuffed_sync_link_stream* s, link_stuffed_sync_link_any_message* out) {
    bool ok;
    s->mode_ = link_stuffed_sync_link_mode_message_;
    s->msg_ = out;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = link_stuffed_sync_link_mode_deliver_;
    s->msg_ = NULL;
    return ok;
}

gmsg_poll link_stuffed_sync_link_stream_poll_event(link_stuffed_sync_link_stream* s, link_stuffed_sync_link_event* out) {
    gmsg_step step;
    s->mode_ = link_stuffed_sync_link_mode_capture_;
    step = gmsg_stream_step(&s->base);
    s->mode_ = link_stuffed_sync_link_mode_deliver_;
    if (step.kind == GMSG_STEP_NEED_MORE) return GMSG_POLL_NEED_MORE;
    if (step.kind == GMSG_STEP_ERROR) {
        out->message.kind = LINK_STUFFED_SYNC_LINK_NONE;
        out->error = step.error;
        out->data = step.data;
        out->size = step.size;
        return GMSG_POLL_ERROR;
    }
    out->message = s->got_.message;
    out->error = GMSG_OK;
    out->data = NULL;
    out->size = 0;
    return GMSG_POLL_MESSAGE;
}

bool link_stuffed_sync_link_stream_poll_for(link_stuffed_sync_link_stream* s, link_stuffed_sync_link_kind kind, link_stuffed_sync_link_any_view* out) {
    bool hit = false;
    s->mode_ = link_stuffed_sync_link_mode_for_;
    s->want_ = kind;
    while (gmsg_stream_pull(&s->base)) {
        if (s->got_.message.kind == kind) {
            *out = s->got_.message;
            hit = true;
            break;
        }
    }
    s->mode_ = link_stuffed_sync_link_mode_deliver_;
    return hit;
}

static void link_stuffed_sync_link_stream_error_(gmsg_stream* s, gmsg_error e, const uint8_t* data, size_t n) {
    const link_stuffed_sync_link_callbacks* cb = &((link_stuffed_sync_link_stream*)s)->cb;
    if (cb->on_error) cb->on_error(cb->ctx, e, data, n);
}

gmsg_error link_stuffed_sync_link_stream_init(link_stuffed_sync_link_stream* s, uint8_t* buf, size_t size) {
    gmsg_memset(s, 0, sizeof *s);  /* callbacks cleared, deliver mode */
    return gmsg_stream_init(&s->base, buf, size, LINK_STUFFED_SYNC_LINK_MAX_FRAME, link_stuffed_sync_link_scan_, link_stuffed_sync_link_stream_process_, link_stuffed_sync_link_stream_error_);
}

gmsg_error link_stuffed_sync_link_encode_data(const link_stuffed_data* m, uint8_t* out, size_t capacity, size_t* written) {
    link_stuffed_sync_link_header h;
    gmsg_memset(&h, 0, sizeof h);
    return link_stuffed_sync_link_encode_data_with_header(&h, m, out, capacity, written);
}

gmsg_error link_stuffed_sync_link_encode_data_with_header(const link_stuffed_sync_link_header* hdr, const link_stuffed_data* m, uint8_t* out, size_t capacity, size_t* written) {
    link_stuffed_sync_link_header h = *hdr;
    gmsg_writer w = gmsg_writer_init(out, capacity);
    gmsg_error e = GMSG_OK;
    if (written) *written = 0;
    if ((e = gmsg_write_bytes(&w, link_stuffed_sync_link_prefix_, 1)) != GMSG_OK) return e;
    const size_t header_at = w.pos;
    (void)header_at;
    h.kind = ((uint8_t)INT64_C(1));
    if ((e = link_stuffed_sync_link_header_write(&h, &w)) != GMSG_OK) return e;
    const size_t body_at = w.pos;
    if ((e = link_stuffed_data_write(m, &w)) != GMSG_OK) return e;
    const size_t body_len = w.pos - body_at;
    (void)body_len;
    {
        const int64_t value = (int64_t)(body_len) - (INT64_C(0));
        if (value < 0 || (uint64_t)value > UINT64_C(255)) return GMSG_ERR_BAD_LENGTH;
        gmsg_write_patch_uint(&w, header_at + 1, 1, GMSG_ENDIAN_BIG, (uint64_t)value);
    }
    const uint64_t cs = (uint64_t)gmsg_crc16_ccitt_compute(out + header_at, w.pos - header_at);
    if ((e = gmsg_write_uint(&w, 2, GMSG_ENDIAN_BIG, cs)) != GMSG_OK) return e;
    size_t total = w.pos;
    {
        size_t esc_n = 0;
        if ((e = gmsg_escape_in_place(out, capacity, 1, total - 1, &link_stuffed_sync_link_framing_.escape, &esc_n)) != GMSG_OK) return e;
        total = 1 + esc_n;
    }
    if (written) *written = total;
    return GMSG_OK;
}

gmsg_error link_stuffed_sync_link_encode_ping(const link_stuffed_ping* m, uint8_t* out, size_t capacity, size_t* written) {
    link_stuffed_sync_link_header h;
    gmsg_memset(&h, 0, sizeof h);
    return link_stuffed_sync_link_encode_ping_with_header(&h, m, out, capacity, written);
}

gmsg_error link_stuffed_sync_link_encode_ping_with_header(const link_stuffed_sync_link_header* hdr, const link_stuffed_ping* m, uint8_t* out, size_t capacity, size_t* written) {
    link_stuffed_sync_link_header h = *hdr;
    gmsg_writer w = gmsg_writer_init(out, capacity);
    gmsg_error e = GMSG_OK;
    if (written) *written = 0;
    if ((e = gmsg_write_bytes(&w, link_stuffed_sync_link_prefix_, 1)) != GMSG_OK) return e;
    const size_t header_at = w.pos;
    (void)header_at;
    h.kind = ((uint8_t)INT64_C(2));
    if ((e = link_stuffed_sync_link_header_write(&h, &w)) != GMSG_OK) return e;
    const size_t body_at = w.pos;
    if ((e = link_stuffed_ping_write(m, &w)) != GMSG_OK) return e;
    const size_t body_len = w.pos - body_at;
    (void)body_len;
    {
        const int64_t value = (int64_t)(body_len) - (INT64_C(0));
        if (value < 0 || (uint64_t)value > UINT64_C(255)) return GMSG_ERR_BAD_LENGTH;
        gmsg_write_patch_uint(&w, header_at + 1, 1, GMSG_ENDIAN_BIG, (uint64_t)value);
    }
    const uint64_t cs = (uint64_t)gmsg_crc16_ccitt_compute(out + header_at, w.pos - header_at);
    if ((e = gmsg_write_uint(&w, 2, GMSG_ENDIAN_BIG, cs)) != GMSG_OK) return e;
    size_t total = w.pos;
    {
        size_t esc_n = 0;
        if ((e = gmsg_escape_in_place(out, capacity, 1, total - 1, &link_stuffed_sync_link_framing_.escape, &esc_n)) != GMSG_OK) return e;
        total = 1 + esc_n;
    }
    if (written) *written = total;
    return GMSG_OK;
}

gmsg_error link_stuffed_sync_link_encode(const link_stuffed_sync_link_any_message* m, uint8_t* out, size_t capacity, size_t* written) {
    switch (m->kind) {
        case LINK_STUFFED_SYNC_LINK_DATA: return link_stuffed_sync_link_encode_data(&m->as.data, out, capacity, written);
        case LINK_STUFFED_SYNC_LINK_PING: return link_stuffed_sync_link_encode_ping(&m->as.ping, out, capacity, written);
        default: break;
    }
    if (written) *written = 0;
    return GMSG_ERR_UNKNOWN_TYPE;
}

/* ---- WireChecksumHeader ------------------------------------------------------------------------------ */

gmsg_error link_stuffed_wire_checksum_header_read(gmsg_reader* r, link_stuffed_wire_checksum_header* m) {
    gmsg_error e = GMSG_OK;
    (void)r;
    (void)m;
    {
        uint8_t v0 = 0;
        if ((e = gmsg_read_u8(r, GMSG_ENDIAN_BIG, &v0)) != GMSG_OK) return e;
        m->kind = v0;
    }
    {
        uint8_t v0 = 0;
        if ((e = gmsg_read_u8(r, GMSG_ENDIAN_BIG, &v0)) != GMSG_OK) return e;
        m->len = v0;
    }
    return e;
}

gmsg_error link_stuffed_wire_checksum_header_write(const link_stuffed_wire_checksum_header* m, gmsg_writer* w) {
    gmsg_error e = GMSG_OK;
    (void)w;
    (void)m;
    if ((e = gmsg_write_u8(w, GMSG_ENDIAN_BIG, m->kind)) != GMSG_OK) return e;
    if ((e = gmsg_write_u8(w, GMSG_ENDIAN_BIG, m->len)) != GMSG_OK) return e;
    return e;
}

gmsg_error link_stuffed_wire_checksum_header_decode(const uint8_t* data, size_t size, link_stuffed_wire_checksum_header* out) {
    gmsg_reader r = gmsg_reader_init(data, size);
    gmsg_memset(out, 0, sizeof *out);
    return link_stuffed_wire_checksum_header_read(&r, out);
}

gmsg_error link_stuffed_wire_checksum_header_decode_extra(const uint8_t* data, size_t size, link_stuffed_wire_checksum_header* out, size_t* extra) {
    gmsg_reader r = gmsg_reader_init(data, size);
    gmsg_error e;
    gmsg_memset(out, 0, sizeof *out);
    e = link_stuffed_wire_checksum_header_read(&r, out);
    *extra = e == GMSG_OK ? size - r.pos : 0;
    return e;
}

gmsg_error link_stuffed_wire_checksum_header_encode(const link_stuffed_wire_checksum_header* m, uint8_t* out, size_t capacity, size_t* written) {
    gmsg_writer w = gmsg_writer_init(out, capacity);
    const gmsg_error e = link_stuffed_wire_checksum_header_write(m, &w);
    if (written) *written = e == GMSG_OK ? w.pos : 0;
    return e;
}

void link_stuffed_wire_checksum_header_print(const link_stuffed_wire_checksum_header* m, gmsg_printer* p) {
    (void)m;
    gmsg_print_begin(p, "WireChecksumHeader");
    gmsg_print_key(p, "kind");
    gmsg_print_u64(p, (uint64_t)m->kind);
    gmsg_print_key(p, "len");
    gmsg_print_u64(p, (uint64_t)m->len);
    gmsg_print_end(p);
}

gmsg_error link_stuffed_wire_checksum_header_view_from(const uint8_t* data, size_t size, link_stuffed_wire_checksum_header_view* out) {
    gmsg_error e = GMSG_OK;
    (void)e;
    if (size < 2) return GMSG_ERR_TRUNCATED;
    out->data = data;
    out->size = 2;
    out->extra = size - 2;
    return GMSG_OK;
}

link_stuffed_wire_checksum_header_view link_stuffed_wire_checksum_header_view_unchecked(const uint8_t* data, size_t size) {
    link_stuffed_wire_checksum_header_view v;
    gmsg_memset(&v, 0, sizeof v);
    v.data = data;
    v.size = 2;
    v.extra = size - 2;
    return v;
}

gmsg_error link_stuffed_wire_checksum_header_view_to_struct(const link_stuffed_wire_checksum_header_view* v, link_stuffed_wire_checksum_header* out) {
    return link_stuffed_wire_checksum_header_decode(v->data, v->size, out);
}

void link_stuffed_wire_checksum_header_view_print(const link_stuffed_wire_checksum_header_view* v, gmsg_printer* p) {
    (void)v;
    gmsg_print_begin(p, "WireChecksumHeader");
    gmsg_print_key(p, "kind");
    gmsg_print_u64(p, (uint64_t)link_stuffed_wire_checksum_header_view_kind(v));
    gmsg_print_key(p, "len");
    gmsg_print_u64(p, (uint64_t)link_stuffed_wire_checksum_header_view_len(v));
    gmsg_print_end(p);
}

/* ==== protocol WireChecksum ======================================================================== */

void link_stuffed_wire_checksum_any_view_print(const link_stuffed_wire_checksum_any_view* v, gmsg_printer* p) {
    switch (v->kind) {
        case LINK_STUFFED_WIRE_CHECKSUM_DATA: link_stuffed_data_view_print(&v->as.data, p); break;
        case LINK_STUFFED_WIRE_CHECKSUM_PING: link_stuffed_ping_view_print(&v->as.ping, p); break;
        default: gmsg_print_text(p, "<none>", 6); break;
    }
}

void link_stuffed_wire_checksum_any_message_print(const link_stuffed_wire_checksum_any_message* v, gmsg_printer* p) {
    switch (v->kind) {
        case LINK_STUFFED_WIRE_CHECKSUM_DATA: link_stuffed_data_print(&v->as.data, p); break;
        case LINK_STUFFED_WIRE_CHECKSUM_PING: link_stuffed_ping_print(&v->as.ping, p); break;
        default: gmsg_print_text(p, "<none>", 6); break;
    }
}

static const uint8_t link_stuffed_wire_checksum_prefix_[1] = {0x80};
static const gmsg_length_prefixed_config link_stuffed_wire_checksum_framing_ = {{{0x80}, 1}, 2, 1, GMSG_ENDIAN_BIG, INT64_C(5), 5, 251, {true, 0x81, GMSG_ESCAPE_TABLE, 0x00, 2, {0x80, 0x81}, {0x00, 0x01}, {0x0u, 0x0u, 0x0u, 0x0u, 0x3u, 0x0u, 0x0u, 0x0u}}, 0, false, 0, 0, false};
/* Scan for a frame; a length the message type cannot have (shorter than the message) is rejected with BAD_LENGTH as soon as the header has arrived. */
static gmsg_frame_scan link_stuffed_wire_checksum_scan_(const uint8_t* b, size_t n) {
    const gmsg_frame_scan s = gmsg_scan_length_prefixed(b, n, &link_stuffed_wire_checksum_framing_);
    uint8_t h[2];
    link_stuffed_wire_checksum_header_view hv;
    int64_t body;
    if (s.kind == GMSG_SCAN_SKIP) return s;
    if (!gmsg_read_frame_header(b, n, link_stuffed_wire_checksum_framing_.sync.len, &link_stuffed_wire_checksum_framing_.escape, h, 2)) return s;
    hv = link_stuffed_wire_checksum_header_view_unchecked(h, 2);
    body = (int64_t)link_stuffed_wire_checksum_header_view_len(&hv) + INT64_C(0);
    switch ((int64_t)link_stuffed_wire_checksum_header_view_kind(&hv)) {
        case INT64_C(1): if (body < 1) return gmsg_scan_skip(1, GMSG_ERR_BAD_LENGTH); break;  /* Data */
        case INT64_C(2): if (body < 4) return gmsg_scan_skip(1, GMSG_ERR_BAD_LENGTH); break;  /* Ping */
        default: break;
    }
    return s;
}

/* A validated frame split into its parts (pointers into the frame buffer). */
typedef struct link_stuffed_wire_checksum_frame_ {
    link_stuffed_wire_checksum_header_view header;
    const uint8_t* body;
    size_t body_size;
    size_t unescaped_n;  /* size of the unescaped part (to restore the frame) */
} link_stuffed_wire_checksum_frame_;

/* Split an unescaped frame into header and body. */
static gmsg_error link_stuffed_wire_checksum_split_(const uint8_t* frame, const uint8_t* interior, size_t interior_n, link_stuffed_wire_checksum_frame_* f) {
    gmsg_error e = GMSG_OK;
    (void)e;
    (void)frame;
    if (interior_n < 4) return GMSG_ERR_TRUNCATED;
    if ((e = link_stuffed_wire_checksum_header_view_from(interior, 2, &f->header)) != GMSG_OK) return e;
    f->body = interior + 2;
    f->body_size = interior_n - 2 - 2;
    return GMSG_OK;
}

/* Escape the unescaped part of an opened frame again (the frame then holds the bytes as received). */
static void link_stuffed_wire_checksum_restore_(uint8_t* frame, size_t size, size_t unescaped_n) {
    size_t k = 0;
    (void)gmsg_escape_in_place(frame, size - 0, 1, unescaped_n, &link_stuffed_wire_checksum_framing_.escape, &k);
}

/* Validate one complete frame (as delimited by the scanner) and split it into header and body. The checksum is verified first; the frame is unescaped in place, and holds the bytes as received again on failure. */
static gmsg_error link_stuffed_wire_checksum_open_(uint8_t* frame, size_t size, link_stuffed_wire_checksum_frame_* f) {
    gmsg_error e = GMSG_OK;
    (void)e;
    if (size < 5) return GMSG_ERR_TRUNCATED;
    uint64_t computed = 0;  /* checksum.over: wire */
    {
        const uint8_t* wire = frame + 1;
        const size_t wire_n = size - 1 - 0;
        size_t un = 0;
        if ((e = gmsg_unescaped_size(wire, wire_n, &link_stuffed_wire_checksum_framing_.escape, &un)) != GMSG_OK) return e;
        if (un < 4) return GMSG_ERR_TRUNCATED;
        const gmsg_escape_walk t = gmsg_walk_escaped(wire, wire_n, 0, un - 2, &link_stuffed_wire_checksum_framing_.escape, 0, NULL, 0);
        if (t.kind != GMSG_WALK_DONE) return t.kind == GMSG_WALK_BAD ? t.error : GMSG_ERR_TRUNCATED;
        computed = (uint64_t)gmsg_crc16_ccitt_compute(wire, t.wire);
    }
    uint8_t* wire = frame + 1;
    const size_t wire_n = size - 1 - 0;
    size_t un = 0;
    if ((e = gmsg_check_escaped(wire, wire_n, &link_stuffed_wire_checksum_framing_.escape, &un)) != GMSG_OK) return e;
    if (un < 4) return GMSG_ERR_TRUNCATED;
    {
        uint8_t sb[2];
        uint64_t stored;
        size_t k = 0, pn = 0;
        const uint8_t* pp = NULL;
        gmsg_unescape_iter it;
        gmsg_unescape_iter_init(&it, wire, wire_n, &link_stuffed_wire_checksum_framing_.escape, un - 2, un);
        while (gmsg_unescape_next(&it, &pp, &pn)) {
            size_t j;
            for (j = 0; j < pn; ++j) sb[k++] = pp[j];
        }
        stored = gmsg_load_uint(sb, 2, GMSG_ENDIAN_BIG);
        if (stored != computed) return GMSG_ERR_BAD_CHECKSUM;
    }
    (void)gmsg_unescape_in_place(wire, wire_n, &link_stuffed_wire_checksum_framing_.escape, &un);
    e = link_stuffed_wire_checksum_split_(frame, wire, un, f);
    if (e != GMSG_OK) link_stuffed_wire_checksum_restore_(frame, size, un);
    else f->unescaped_n = un;
    return e;
}

/* Decode the message view selected by the frame's type id (message_type). */
static gmsg_error link_stuffed_wire_checksum_select_(const link_stuffed_wire_checksum_frame_* f, link_stuffed_wire_checksum_any_view* out) {
    switch ((int64_t)link_stuffed_wire_checksum_header_view_kind(&f->header)) {
        case INT64_C(1): {  /* Data */
            out->kind = LINK_STUFFED_WIRE_CHECKSUM_DATA;
            return link_stuffed_data_view_from(f->body, f->body_size, &out->as.data);
        }
        case INT64_C(2): {  /* Ping */
            out->kind = LINK_STUFFED_WIRE_CHECKSUM_PING;
            return link_stuffed_ping_view_from(f->body, f->body_size, &out->as.ping);
        }
        default: break;
    }
    out->kind = LINK_STUFFED_WIRE_CHECKSUM_NONE;
    return GMSG_ERR_UNKNOWN_TYPE;
}

static gmsg_error link_stuffed_wire_checksum_select_restore_(uint8_t* frame, size_t size, const link_stuffed_wire_checksum_frame_* f, link_stuffed_wire_checksum_any_view* out) {
    const gmsg_error e = link_stuffed_wire_checksum_select_(f, out);
    if (e != GMSG_OK) link_stuffed_wire_checksum_restore_(frame, size, f->unescaped_n);
    return e;
}

static void link_stuffed_wire_checksum_deliver_(const link_stuffed_wire_checksum_callbacks* cb, const link_stuffed_wire_checksum_frame_* f, const link_stuffed_wire_checksum_any_view* v) {
    switch (v->kind) {
        case LINK_STUFFED_WIRE_CHECKSUM_DATA: if (cb->on_data) cb->on_data(cb->ctx, &f->header, &v->as.data); break;
        case LINK_STUFFED_WIRE_CHECKSUM_PING: if (cb->on_ping) cb->on_ping(cb->ctx, &f->header, &v->as.ping); break;
        default: break;
    }
    if (cb->on_frame) cb->on_frame(cb->ctx, &f->header, v);
}

/* Validate a complete frame, select its message and deliver it (C++: P::process). */
static gmsg_error link_stuffed_wire_checksum_process_frame_(uint8_t* frame, size_t size, const link_stuffed_wire_checksum_callbacks* cb) {
    link_stuffed_wire_checksum_frame_ f;
    link_stuffed_wire_checksum_any_view v;
    gmsg_error e = GMSG_OK;
    if ((e = link_stuffed_wire_checksum_open_(frame, size, &f)) != GMSG_OK) return e;
    if ((e = link_stuffed_wire_checksum_select_restore_(frame, size, &f, &v)) != GMSG_OK) return e;
    if (cb) link_stuffed_wire_checksum_deliver_(cb, &f, &v);
    return GMSG_OK;
}

gmsg_error link_stuffed_wire_checksum_parse(uint8_t* data, size_t size, link_stuffed_wire_checksum_any_view* out) {
    link_stuffed_wire_checksum_frame_ f;
    gmsg_error e = GMSG_OK;
    const gmsg_frame_scan s = link_stuffed_wire_checksum_scan_(data, size);
    if (s.kind == GMSG_SCAN_NEED_MORE) return GMSG_ERR_TRUNCATED;
    if (s.kind == GMSG_SCAN_SKIP) return s.error == GMSG_OK ? GMSG_ERR_BAD_SYNC : s.error;
    if ((e = link_stuffed_wire_checksum_open_(data, s.size, &f)) != GMSG_OK) return e;
    return link_stuffed_wire_checksum_select_restore_(data, s.size, &f, out);
}

gmsg_error link_stuffed_wire_checksum_decode(uint8_t* data, size_t size, link_stuffed_wire_checksum_any_message* out) {
    link_stuffed_wire_checksum_any_view v;
    gmsg_error e = GMSG_OK;
    if ((e = link_stuffed_wire_checksum_parse(data, size, &v)) != GMSG_OK) return e;
    out->kind = v.kind;
    switch (v.kind) {
        case LINK_STUFFED_WIRE_CHECKSUM_DATA: return link_stuffed_data_view_to_struct(&v.as.data, &out->as.data);
        case LINK_STUFFED_WIRE_CHECKSUM_PING: return link_stuffed_ping_view_to_struct(&v.as.ping, &out->as.ping);
        default: return GMSG_ERR_UNKNOWN_TYPE;
    }
}

gmsg_error link_stuffed_wire_checksum_process(uint8_t* data, size_t size, const link_stuffed_wire_checksum_callbacks* cb) {
    const gmsg_frame_scan s = link_stuffed_wire_checksum_scan_(data, size);
    if (s.kind == GMSG_SCAN_NEED_MORE) return GMSG_ERR_TRUNCATED;
    if (s.kind == GMSG_SCAN_SKIP) return s.error == GMSG_OK ? GMSG_ERR_BAD_SYNC : s.error;
    return link_stuffed_wire_checksum_process_frame_(data, s.size, cb);
}

/* stream modes: deliver to callbacks (feed / next), or capture for the pull API */
enum { link_stuffed_wire_checksum_mode_deliver_ = 0, link_stuffed_wire_checksum_mode_capture_ = 1, link_stuffed_wire_checksum_mode_message_ = 2, link_stuffed_wire_checksum_mode_for_ = 3 };

/* Data after the message (bytes, or tokens for text messages). */
static size_t link_stuffed_wire_checksum_extra_(const link_stuffed_wire_checksum_any_view* v) {
    switch (v->kind) {
        case LINK_STUFFED_WIRE_CHECKSUM_DATA: return link_stuffed_data_view_extra_bytes(&v->as.data);
        case LINK_STUFFED_WIRE_CHECKSUM_PING: return link_stuffed_ping_view_extra_bytes(&v->as.ping);
        default: return 0;
    }
}

static gmsg_error link_stuffed_wire_checksum_stream_process_(gmsg_stream* gs, uint8_t* frame, size_t n) {
    link_stuffed_wire_checksum_stream* s = (link_stuffed_wire_checksum_stream*)gs;
    link_stuffed_wire_checksum_frame_ f;
    gmsg_error e = GMSG_OK;
    if ((e = link_stuffed_wire_checksum_open_(frame, n, &f)) != GMSG_OK) return e;
    if (s->mode_ == link_stuffed_wire_checksum_mode_deliver_) {
        link_stuffed_wire_checksum_any_view v;
        if ((e = link_stuffed_wire_checksum_select_restore_(frame, n, &f, &v)) != GMSG_OK) return e;
        gs->last_extra = link_stuffed_wire_checksum_extra_(&v);
        link_stuffed_wire_checksum_deliver_(&s->cb, &f, &v);
        return GMSG_OK;
    }
    if ((e = link_stuffed_wire_checksum_select_restore_(frame, n, &f, &s->got_.message)) != GMSG_OK) return e;
    gs->last_extra = s->got_.extra = link_stuffed_wire_checksum_extra_(&s->got_.message);
    s->got_.header = f.header;
    s->got_.bytes = frame;
    s->got_.size = n;
    if (s->mode_ == link_stuffed_wire_checksum_mode_for_ && s->got_.message.kind != s->want_) {
        link_stuffed_wire_checksum_deliver_(&s->cb, &f, &s->got_.message);  /* not the awaited message: to the callbacks */
        s->got_.message.kind = LINK_STUFFED_WIRE_CHECKSUM_NONE;
    }
    if (s->mode_ == link_stuffed_wire_checksum_mode_message_) {
        switch (s->got_.message.kind) {
            case LINK_STUFFED_WIRE_CHECKSUM_DATA: s->msg_->kind = LINK_STUFFED_WIRE_CHECKSUM_DATA; e = link_stuffed_data_view_to_struct(&s->got_.message.as.data, &s->msg_->as.data); break;
            case LINK_STUFFED_WIRE_CHECKSUM_PING: s->msg_->kind = LINK_STUFFED_WIRE_CHECKSUM_PING; e = link_stuffed_ping_view_to_struct(&s->got_.message.as.ping, &s->msg_->as.ping); break;
            default: e = GMSG_ERR_UNKNOWN_TYPE; break;
        }
        if (e != GMSG_OK) link_stuffed_wire_checksum_restore_(frame, n, f.unescaped_n);  /* a frame that fails is left as received */
        return e;
    }
    return GMSG_OK;
}

bool link_stuffed_wire_checksum_stream_poll(link_stuffed_wire_checksum_stream* s, link_stuffed_wire_checksum_any_view* out) {
    bool ok;
    s->mode_ = link_stuffed_wire_checksum_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = link_stuffed_wire_checksum_mode_deliver_;
    if (ok) *out = s->got_.message;
    return ok;
}

bool link_stuffed_wire_checksum_stream_poll_frame(link_stuffed_wire_checksum_stream* s, link_stuffed_wire_checksum_received* out) {
    bool ok;
    s->mode_ = link_stuffed_wire_checksum_mode_capture_;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = link_stuffed_wire_checksum_mode_deliver_;
    if (ok) *out = s->got_;
    return ok;
}

bool link_stuffed_wire_checksum_stream_poll_message(link_stuffed_wire_checksum_stream* s, link_stuffed_wire_checksum_any_message* out) {
    bool ok;
    s->mode_ = link_stuffed_wire_checksum_mode_message_;
    s->msg_ = out;
    ok = gmsg_stream_pull(&s->base);
    s->mode_ = link_stuffed_wire_checksum_mode_deliver_;
    s->msg_ = NULL;
    return ok;
}

gmsg_poll link_stuffed_wire_checksum_stream_poll_event(link_stuffed_wire_checksum_stream* s, link_stuffed_wire_checksum_event* out) {
    gmsg_step step;
    s->mode_ = link_stuffed_wire_checksum_mode_capture_;
    step = gmsg_stream_step(&s->base);
    s->mode_ = link_stuffed_wire_checksum_mode_deliver_;
    if (step.kind == GMSG_STEP_NEED_MORE) return GMSG_POLL_NEED_MORE;
    if (step.kind == GMSG_STEP_ERROR) {
        out->message.kind = LINK_STUFFED_WIRE_CHECKSUM_NONE;
        out->error = step.error;
        out->data = step.data;
        out->size = step.size;
        return GMSG_POLL_ERROR;
    }
    out->message = s->got_.message;
    out->error = GMSG_OK;
    out->data = NULL;
    out->size = 0;
    return GMSG_POLL_MESSAGE;
}

bool link_stuffed_wire_checksum_stream_poll_for(link_stuffed_wire_checksum_stream* s, link_stuffed_wire_checksum_kind kind, link_stuffed_wire_checksum_any_view* out) {
    bool hit = false;
    s->mode_ = link_stuffed_wire_checksum_mode_for_;
    s->want_ = kind;
    while (gmsg_stream_pull(&s->base)) {
        if (s->got_.message.kind == kind) {
            *out = s->got_.message;
            hit = true;
            break;
        }
    }
    s->mode_ = link_stuffed_wire_checksum_mode_deliver_;
    return hit;
}

static void link_stuffed_wire_checksum_stream_error_(gmsg_stream* s, gmsg_error e, const uint8_t* data, size_t n) {
    const link_stuffed_wire_checksum_callbacks* cb = &((link_stuffed_wire_checksum_stream*)s)->cb;
    if (cb->on_error) cb->on_error(cb->ctx, e, data, n);
}

gmsg_error link_stuffed_wire_checksum_stream_init(link_stuffed_wire_checksum_stream* s, uint8_t* buf, size_t size) {
    gmsg_memset(s, 0, sizeof *s);  /* callbacks cleared, deliver mode */
    return gmsg_stream_init(&s->base, buf, size, LINK_STUFFED_WIRE_CHECKSUM_MAX_FRAME, link_stuffed_wire_checksum_scan_, link_stuffed_wire_checksum_stream_process_, link_stuffed_wire_checksum_stream_error_);
}

gmsg_error link_stuffed_wire_checksum_encode_data(const link_stuffed_data* m, uint8_t* out, size_t capacity, size_t* written) {
    link_stuffed_wire_checksum_header h;
    gmsg_memset(&h, 0, sizeof h);
    return link_stuffed_wire_checksum_encode_data_with_header(&h, m, out, capacity, written);
}

gmsg_error link_stuffed_wire_checksum_encode_data_with_header(const link_stuffed_wire_checksum_header* hdr, const link_stuffed_data* m, uint8_t* out, size_t capacity, size_t* written) {
    link_stuffed_wire_checksum_header h = *hdr;
    gmsg_writer w = gmsg_writer_init(out, capacity);
    gmsg_error e = GMSG_OK;
    if (written) *written = 0;
    if ((e = gmsg_write_bytes(&w, link_stuffed_wire_checksum_prefix_, 1)) != GMSG_OK) return e;
    const size_t header_at = w.pos;
    (void)header_at;
    h.kind = ((uint8_t)INT64_C(1));
    if ((e = link_stuffed_wire_checksum_header_write(&h, &w)) != GMSG_OK) return e;
    const size_t body_at = w.pos;
    if ((e = link_stuffed_data_write(m, &w)) != GMSG_OK) return e;
    const size_t body_len = w.pos - body_at;
    (void)body_len;
    {
        const int64_t value = (int64_t)(body_len) - (INT64_C(0));
        if (value < 0 || (uint64_t)value > UINT64_C(255)) return GMSG_ERR_BAD_LENGTH;
        gmsg_write_patch_uint(&w, header_at + 1, 1, GMSG_ENDIAN_BIG, (uint64_t)value);
    }
    size_t total = w.pos;
    {
        size_t esc_n = 0;
        if ((e = gmsg_escape_in_place(out, capacity, 1, total - 1, &link_stuffed_wire_checksum_framing_.escape, &esc_n)) != GMSG_OK) return e;
        total = 1 + esc_n;
    }
    const uint64_t cs = (uint64_t)gmsg_crc16_ccitt_compute(out + 1, total - 1);  /* over the wire bytes */
    if (capacity - total < 2) return GMSG_ERR_BUFFER_FULL;
    gmsg_store_uint(out + total, 2, cs, GMSG_ENDIAN_BIG);
    {
        size_t esc_n = 0;
        if ((e = gmsg_escape_in_place(out, capacity, total, 2, &link_stuffed_wire_checksum_framing_.escape, &esc_n)) != GMSG_OK) return e;
        total += esc_n;
    }
    if (written) *written = total;
    return GMSG_OK;
}

gmsg_error link_stuffed_wire_checksum_encode_ping(const link_stuffed_ping* m, uint8_t* out, size_t capacity, size_t* written) {
    link_stuffed_wire_checksum_header h;
    gmsg_memset(&h, 0, sizeof h);
    return link_stuffed_wire_checksum_encode_ping_with_header(&h, m, out, capacity, written);
}

gmsg_error link_stuffed_wire_checksum_encode_ping_with_header(const link_stuffed_wire_checksum_header* hdr, const link_stuffed_ping* m, uint8_t* out, size_t capacity, size_t* written) {
    link_stuffed_wire_checksum_header h = *hdr;
    gmsg_writer w = gmsg_writer_init(out, capacity);
    gmsg_error e = GMSG_OK;
    if (written) *written = 0;
    if ((e = gmsg_write_bytes(&w, link_stuffed_wire_checksum_prefix_, 1)) != GMSG_OK) return e;
    const size_t header_at = w.pos;
    (void)header_at;
    h.kind = ((uint8_t)INT64_C(2));
    if ((e = link_stuffed_wire_checksum_header_write(&h, &w)) != GMSG_OK) return e;
    const size_t body_at = w.pos;
    if ((e = link_stuffed_ping_write(m, &w)) != GMSG_OK) return e;
    const size_t body_len = w.pos - body_at;
    (void)body_len;
    {
        const int64_t value = (int64_t)(body_len) - (INT64_C(0));
        if (value < 0 || (uint64_t)value > UINT64_C(255)) return GMSG_ERR_BAD_LENGTH;
        gmsg_write_patch_uint(&w, header_at + 1, 1, GMSG_ENDIAN_BIG, (uint64_t)value);
    }
    size_t total = w.pos;
    {
        size_t esc_n = 0;
        if ((e = gmsg_escape_in_place(out, capacity, 1, total - 1, &link_stuffed_wire_checksum_framing_.escape, &esc_n)) != GMSG_OK) return e;
        total = 1 + esc_n;
    }
    const uint64_t cs = (uint64_t)gmsg_crc16_ccitt_compute(out + 1, total - 1);  /* over the wire bytes */
    if (capacity - total < 2) return GMSG_ERR_BUFFER_FULL;
    gmsg_store_uint(out + total, 2, cs, GMSG_ENDIAN_BIG);
    {
        size_t esc_n = 0;
        if ((e = gmsg_escape_in_place(out, capacity, total, 2, &link_stuffed_wire_checksum_framing_.escape, &esc_n)) != GMSG_OK) return e;
        total += esc_n;
    }
    if (written) *written = total;
    return GMSG_OK;
}

gmsg_error link_stuffed_wire_checksum_encode(const link_stuffed_wire_checksum_any_message* m, uint8_t* out, size_t capacity, size_t* written) {
    switch (m->kind) {
        case LINK_STUFFED_WIRE_CHECKSUM_DATA: return link_stuffed_wire_checksum_encode_data(&m->as.data, out, capacity, written);
        case LINK_STUFFED_WIRE_CHECKSUM_PING: return link_stuffed_wire_checksum_encode_ping(&m->as.ping, out, capacity, written);
        default: break;
    }
    if (written) *written = 0;
    return GMSG_ERR_UNKNOWN_TYPE;
}

/* ---- WireLengthHeader -------------------------------------------------------------------------------- */

gmsg_error link_stuffed_wire_length_header_read(gmsg_reader* r, link_stuffed_wire_length_header* m) {
    gmsg_error e = GMSG_OK;
    (void)r;
    (void)m;
    {
        uint8_t v0 = 0;
        if ((e = gmsg_read_u8(r, GMSG_ENDIAN_BIG, &v0)) != GMSG_OK) return e;
        m->kind = v0;
    }
    {
        uint8_t v0 = 0;
        if ((e = gmsg_read_u8(r, GMSG_ENDIAN_BIG, &v0)) != GMSG_OK) return e;
        m->len = v0;
    }
    return e;
}

gmsg_error link_stuffed_wire_length_header_write(const link_stuffed_wire_length_header* m, gmsg_writer* w) {
    gmsg_error e = GMSG_OK;
    (void)w;
    (void)m;
    if ((e = gmsg_write_u8(w, GMSG_ENDIAN_BIG, m->kind)) != GMSG_OK) return e;
    if ((e = gmsg_write_u8(w, GMSG_ENDIAN_BIG, m->len)) != GMSG_OK) return e;
    return e;
}

gmsg_error link_stuffed_wire_length_header_decode(const uint8_t* data, size_t size, link_stuffed_wire_length_header* out) {
    gmsg_reader r = gmsg_reader_init(data, size);
    gmsg_memset(out, 0, sizeof *out);
    return link_stuffed_wire_length_header_read(&r, out);
}

gmsg_error link_stuffed_wire_length_header_decode_extra(const uint8_t* data, size_t size, link_stuffed_wire_length_header* out, size_t* extra) {
    gmsg_reader r = gmsg_reader_init(data, size);
    gmsg_error e;
    gmsg_memset(out, 0, sizeof *out);
    e = link_stuffed_wire_length_header_read(&r, out);
    *extra = e == GMSG_OK ? size - r.pos : 0;
    return e;
}

gmsg_error link_stuffed_wire_length_header_encode(const link_stuffed_wire_length_header* m, uint8_t* out, size_t capacity, size_t* written) {
    gmsg_writer w = gmsg_writer_init(out, capacity);
    const gmsg_error e = link_stuffed_wire_length_header_write(m, &w);
    if (written) *written = e == GMSG_OK ? w.pos : 0;
    return e;
}

void link_stuffed_wire_length_header_print(const link_stuffed_wire_length_header* m, gmsg_printer* p) {
    (void)m;
    gmsg_print_begin(p, "WireLengthHeader");
    gmsg_print_key(p, "kind");
    gmsg_print_u64(p, (uint64_t)m->kind);
    gmsg_print_key(p, "len");
    gmsg_print_u64(p, (uint64_t)m->len);
    gmsg_print_end(p);
}

gmsg_error link_stuffed_wire_length_header_view_from(const uint8_t* data, size_t size, link_stuffed_wire_length_header_view* out) {
    gmsg_error e = GMSG_OK;
    (void)e;
    if (size < 2) return GMSG_ERR_TRUNCATED;
    out->data = data;
    out->size = 2;
    out->extra = size - 2;
    return GMSG_OK;
}

link_stuffed_wire_length_header_view link_stuffed_wire_length_header_view_unchecked(const uint8_t* data, size_t size) {
    link_stuffed_wire_length_header_view v;
    gmsg_memset(&v, 0, sizeof v);
    v.data = data;
    v.size = 2;
    v.extra = size - 2;
    return v;
}

gmsg_error link_stuffed_wire_length_header_view_to_struct(const link_stuffed_wire_length_header_view* v, link_stuffed_wire_length_header* out) {
    return link_stuffed_wire_length_header_decode(v->data, v->size, out);
}

void link_stuffed_wire_length_header_view_print(const link_stuffed_wire_length_header_view* v, gmsg_printer* p) {
    (void)v;
    gmsg_print_begin(p, "WireLengthHeader");
    gmsg_print_key(p, "kind");
    gmsg_print_u64(p, (uint64_t)link_stuffed_wire_length_header_view_kind(v));
    gmsg_print_key(p, "len");
    gmsg_print_u64(p, (uint64_t)link_stuffed_wire_length_header_view_len(v));
    gmsg_print_end(p);
}

